'use client';

import { useHealthControllerCheck } from '@/lib/api';
import type { ApiHealth } from '../types';

/**
 * Feature hook for API availability.
 *
 * The Orval hook (`useHealthControllerCheck`) is the transport layer: it
 * owns the request, the cache key and the query lifecycle. This hook is the
 * domain layer — it maps the generated DTO onto `ApiHealth` and normalises
 * the states a screen actually has to render.
 *
 * Why the extra layer:
 * - `src/lib/api/` is regenerated by Orval with `clean: true`, so anything
 *   hand-written there is deleted on the next codegen run. Feature code
 *   lives here instead.
 * - Screens should not branch on the raw query flags. `isPending` is true
 *   forever for a query with `enabled: false`, which is a common source of
 *   "spinner never stops" bugs. This hook returns an explicit status.
 *
 * Note: `isFetching` means "a request is in flight"; `isPending` means "no
 * data yet". Use `status` for what to render.
 */
export function useApiHealth() {
  const query = useHealthControllerCheck();

  const data: ApiHealth | undefined = query.data
    ? {
        status: query.data.status,
        service: query.data.service,
        uptimeSeconds: query.data.uptimeSeconds,
        timestamp: query.data.timestamp,
      }
    : undefined;

  return {
    ...query,
    data,
    /** The API answered and reported a usable status. */
    isHealthy: query.isSuccess && data?.status === 'ok',
    /** A request is currently in flight. */
    isFetching: query.isFetching,
    /** The last attempt failed. */
    isFailed: query.isError,
  };
}
